import CoreGraphics
import Foundation

/// The brush of the house ("Pigmento", exploration 12 §2 and
/// docs/design/color/lenguaje-pictorico.md): the pseudo-random generator,
/// the palette per texture and the ribbon stroke with its impasto. Own work
/// generated by code; no image is read, embedded or traced from anywhere.
///
/// One file, two builds. The app compiles it into the paint engine
/// (`PaintScene`, `PaintRasterizer`) and `scripts/paint/generate.sh`
/// compiles the same file next to `scripts/paint/PaintGenerator.swift` for
/// the pieces painted at build time, so both paint with one generator, one
/// order of random draws and one palette: a seed paints the same strokes in
/// the catalog and on the page. Only CoreGraphics and Foundation, so it
/// builds for iOS and for the macOS command line alike. Nothing here touches
/// the main thread or the audio thread: it draws into whatever context it
/// is handed.
enum Pigment {
    // MARK: Pseudo-random generator (ported as is from the mock-ups)

    /// The LCG of the mock-ups: s = s * 1664525 + 1013904223 mod 2^32,
    /// returned as a double in [0, 1). Every random draw of the mock-up is
    /// made in the same order here, so a seed paints the same composition.
    struct LCG {
        private(set) var state: UInt32

        init(seed: UInt32) { state = seed }

        mutating func next() -> Double {
            state = state &* 1664525 &+ 1013904223
            return Double(state) / 4294967296
        }
    }

    /// FNV-1a over the UTF-16 code units of a string, as the mock-up hashes
    /// a mix name into a seed: 32 bits, offset basis 2166136261, prime
    /// 16777619.
    static func fnv1a(_ text: String) -> UInt32 {
        var hash: UInt32 = 2166136261
        for unit in text.utf16 {
            hash ^= UInt32(unit)
            hash = hash &* 16777619
        }
        return hash
    }

    /// Value noise on a 64 x 64 lattice with smoothstep interpolation, tiled.
    struct ValueNoise {
        private var grid: [Double]

        init(_ rng: inout LCG) {
            grid = (0..<(64 * 64)).map { _ in rng.next() }
        }

        func callAsFunction(_ x: Double, _ y: Double) -> Double {
            func fade(_ t: Double) -> Double { t * t * (3 - 2 * t) }
            let fx = floor(x), fy = floor(y)
            let xi = Int(fx) & 63, yi = Int(fy) & 63
            let xf = x - fx, yf = y - fy
            let a = grid[yi * 64 + xi]
            let b = grid[yi * 64 + ((xi + 1) & 63)]
            let c = grid[((yi + 1) & 63) * 64 + xi]
            let d = grid[((yi + 1) & 63) * 64 + ((xi + 1) & 63)]
            let u = fade(xf), v = fade(yf)
            return (a * (1 - u) + b * u) * (1 - v) + (c * (1 - u) + d * u) * v
        }
    }

    // MARK: Palette (lenguaje-pictorico.md §1)

    struct Tint: Equatable {
        let hex: UInt32

        var r: Double { Double((hex >> 16) & 0xFF) / 255 }
        var g: Double { Double((hex >> 8) & 0xFF) / 255 }
        var b: Double { Double(hex & 0xFF) / 255 }

        func cgColor(alpha: Double = 1) -> CGColor {
            CGColor(srgbRed: CGFloat(r), green: CGFloat(g), blue: CGFloat(b), alpha: CGFloat(alpha))
        }

        /// The mock-up's `mix(h, "#000000", t)`: each channel rounded to 8 bits.
        func towardsBlack(_ t: Double) -> Tint {
            func channel(_ v: UInt32) -> UInt32 { UInt32((Double(v) * (1 - t)).rounded()) }
            return Tint(hex: channel((hex >> 16) & 0xFF) << 16 | channel((hex >> 8) & 0xFF) << 8 | channel(hex & 0xFF))
        }
    }

    static let black = Tint(hex: 0x000000)

    /// Light to base. The lightest tint is the "touch of light"; the darkest
    /// the base. No tint here ever becomes text or a glyph.
    enum Palette {
        static let white = [Tint(hex: 0xE3E0D8), Tint(hex: 0xA9B8C6), Tint(hex: 0x5E6B78)]
        static let pink = [Tint(hex: 0xF3D2B8), Tint(hex: 0xE8A598), Tint(hex: 0xC77B8A), Tint(hex: 0x7A4A5E)]
        static let brown = [Tint(hex: 0xD9A66B), Tint(hex: 0xB07A4A), Tint(hex: 0x7A4E2E), Tint(hex: 0x4A3222)]
        static let rain = [Tint(hex: 0xB9CDD9), Tint(hex: 0x7FA7C9), Tint(hex: 0x4A6B8A), Tint(hex: 0x2E4A5E)]
        static let fan = [Tint(hex: 0xD7DBE0), Tint(hex: 0xB8BFC9), Tint(hex: 0x7C8794), Tint(hex: 0x4F5862)]
        static let ocean = [Tint(hex: 0xCFE7E0), Tint(hex: 0x3FA7B0), Tint(hex: 0x1F6F8B), Tint(hex: 0x0F3C56)]
        static let thunder = [Tint(hex: 0xC9C4E8), Tint(hex: 0x8E7FB8), Tint(hex: 0x6A5A8E), Tint(hex: 0x3A3250)]
        static let campfire = [Tint(hex: 0xFFB15C), Tint(hex: 0xF08A24), Tint(hex: 0xD9442B), Tint(hex: 0x5A2A14)]
        static let brook = [Tint(hex: 0xBFE3C8), Tint(hex: 0x5FB08A), Tint(hex: 0x2F7A5A), Tint(hex: 0x1E4A3A)]
        static let wind = [Tint(hex: 0xE8E0C4), Tint(hex: 0xC9C2A8), Tint(hex: 0x8FA07A), Tint(hex: 0x5F6B55)]
        static let cabin = [Tint(hex: 0xD6CFC8), Tint(hex: 0xB9A9A0), Tint(hex: 0x8A7F96), Tint(hex: 0x5B5566)]
    }

    /// One motif per texture, abstract before figurative (lenguaje §2): the
    /// palette, the pt² of window per ribbon at full level, the weights of
    /// the tints, and whether it is a field (painted first, the ground) or a
    /// bed (painted over the fields).
    enum Motif: String, CaseIterable {
        case white, pink, brown, rain, fan, ocean, thunder, campfire, brook, wind, cabin

        var palette: [Tint] {
            switch self {
            case .white: return Palette.white
            case .pink: return Palette.pink
            case .brown: return Palette.brown
            case .rain: return Palette.rain
            case .fan: return Palette.fan
            case .ocean: return Palette.ocean
            case .thunder: return Palette.thunder
            case .campfire: return Palette.campfire
            case .brook: return Palette.brook
            case .wind: return Palette.wind
            case .cabin: return Palette.cabin
            }
        }

        /// pt² per ribbon at level 100 (the mock-up's DENS).
        var density: Double {
            switch self {
            case .white: return 32
            case .pink: return 70
            case .brown: return 160
            case .rain: return 55
            case .fan: return 60
            case .ocean: return 48
            case .thunder: return 110
            case .campfire: return 120
            case .brook: return 120
            case .wind: return 70
            case .cabin: return 220
            }
        }

        /// Weights of the tints, light to base (the mock-up's PESOS).
        var weights: [Double] {
            switch self {
            case .white: return [1, 4, 6]
            case .pink: return [1, 3, 5, 5]
            case .brown: return [1, 3, 5, 4]
            case .rain: return [1, 3, 5, 6]
            case .fan: return [1, 3, 5, 6]
            case .ocean: return [1, 3, 6, 5]
            case .thunder: return [0, 1, 4, 9]
            case .campfire: return [2, 3, 3, 1]
            case .brook: return [1, 3, 5, 3]
            case .wind: return [1, 4, 5, 3]
            case .cabin: return [1, 3, 6, 4]
            }
        }

        /// Fields are the ground: white, pink, brown, cabin and fan.
        var isField: Bool {
            switch self {
            case .white, .pink, .brown, .cabin, .fan: return true
            case .rain, .ocean, .thunder, .campfire, .brook, .wind: return false
            }
        }

        /// The base direction of the motif in radians, the way the window
        /// slides with the tide: rain falls to the right at 72°, campfire
        /// rises, the rest run horizontal.
        var direction: Double {
            switch self {
            case .rain: return 72 * Double.pi / 180
            case .campfire: return -Double.pi / 2
            default: return 0
            }
        }
    }

    // MARK: Geometry

    struct P: Equatable {
        var x: Double
        var y: Double
    }

    /// A ribbon, ready to paint: its centre line, width, tints and alpha.
    /// `tintIndex` is the base tint in the palette; the light tint is the
    /// one before it. A black ribbon is a tongue of the campfire painted
    /// in burnt black, always dry.
    struct Ribbon: Equatable {
        var points: [P]
        var width: Double
        var alpha: Double
        var tintIndex: Int
        var taper: Bool
        var isBlack: Bool
    }

    static let sRGB = CGColorSpace(name: CGColorSpace.sRGB)!

    /// A ribbon: a centre line with a varying width, filled with a
    /// perpendicular gradient of three stops where two coincide (light to
    /// 0.38, base after, a shadow band on the last 0.12). The dry jump is
    /// the relief of the impasto. Draws into `ctx`, whose user space is in
    /// points with the origin top left.
    static func ribbon(
        _ ctx: CGContext, _ pts: [P], _ w: Double, _ light: Tint, _ base: Tint, _ alpha: Double, taper: Bool = false
    ) {
        guard pts.count >= 2 else { return }
        var left: [P] = [], right: [P] = []
        let last = pts.count - 1
        for i in 0...last {
            let p = pts[i], q = pts[min(i + 1, last)], o = pts[max(i - 1, 0)]
            var dx = q.x - o.x, dy = q.y - o.y
            var len = (dx * dx + dy * dy).squareRoot()
            if len == 0 { len = 1 }
            dx /= len; dy /= len
            let t = Double(i) / Double(last)
            let prof = taper ? (1 - 0.78 * t) : 0.35 + 0.65 * sin(Double.pi * min(1, t * 1.25)) * (1 - 0.25 * t)
            let hw = w * prof * 0.5
            left.append(P(x: p.x - dy * hw, y: p.y + dx * hw))
            right.append(P(x: p.x + dy * hw, y: p.y - dx * hw))
        }
        let a = pts[0], b = pts[last]
        let nx = -(b.y - a.y), ny = b.x - a.x
        var nl = (nx * nx + ny * ny).squareRoot()
        if nl == 0 { nl = 1 }
        let m = P(x: (a.x + b.x) / 2, y: (a.y + b.y) / 2)
        let start = CGPoint(x: m.x - nx / nl * w / 2, y: m.y - ny / nl * w / 2)
        let end = CGPoint(x: m.x + nx / nl * w / 2, y: m.y + ny / nl * w / 2)
        let shadow = black.cgColor(alpha: alpha * 0.35)
        let colors = [light.cgColor(alpha: alpha), light.cgColor(alpha: alpha), base.cgColor(alpha: alpha),
                      base.cgColor(alpha: alpha), shadow, shadow] as CFArray
        let locations: [CGFloat] = [0, 0.38, 0.38, 0.88, 0.88, 1]
        guard let gradient = CGGradient(colorsSpace: sRGB, colors: colors, locations: locations) else { return }

        ctx.saveGState()
        ctx.beginPath()
        ctx.move(to: CGPoint(x: left[0].x, y: left[0].y))
        for p in left { ctx.addLine(to: CGPoint(x: p.x, y: p.y)) }
        for p in right.reversed() { ctx.addLine(to: CGPoint(x: p.x, y: p.y)) }
        ctx.closePath()
        ctx.clip()
        ctx.drawLinearGradient(gradient, start: start, end: end, options: [.drawsBeforeStartLocation, .drawsAfterEndLocation])
        ctx.restoreGState()
    }

    /// Paints a ribbon with the tints of `palette`, from `minimumTint` up:
    /// outside the band of the horizon only the two dark tints of a palette
    /// are allowed (`minimumTint` 2), inside it all four (0).
    static func paint(_ r: Ribbon, palette: [Tint], minimumTint: Int, into ctx: CGContext) {
        if r.isBlack {
            ribbon(ctx, r.points, r.width, black, black, 0.85, taper: true)
            return
        }
        let floor = min(minimumTint, palette.count - 1)
        let k = max(floor, r.tintIndex)
        ribbon(ctx, r.points, r.width, palette[max(floor, k - 1)], palette[k], r.alpha, taper: r.taper)
    }

    /// One-point specks of pure channels: the grain of the paste.
    static func grain(_ ctx: CGContext, width: Double, height: Double, _ R: inout LCG, _ alpha: Double) {
        let n = width * height / 40
        var i = 0.0
        while i < n {
            let r: CGFloat = R.next() > 0.5 ? 1 : 0
            let g: CGFloat = R.next() > 0.5 ? 1 : 0
            let b: CGFloat = R.next() > 0.5 ? 1 : 0
            ctx.setFillColor(CGColor(srgbRed: r, green: g, blue: b, alpha: CGFloat(alpha)))
            let x = R.next() * width, y = R.next() * height
            ctx.fill(CGRect(x: x, y: y, width: 1, height: 1))
            i += 1
        }
    }

    /// A stroke by 1D noise: a base direction and a deviation per step.
    static func strokeNoise(
        _ x0: Double, _ y0: Double, _ ang: Double, _ len: Double, _ steps: Int, _ R: inout LCG, _ dev: Double
    ) -> [P] {
        var pts = [P(x: x0, y: y0)]
        var x = x0, y = y0, a = ang
        for _ in 1...steps {
            a += (R.next() - 0.5) * dev
            x += cos(a) * len / Double(steps)
            y += sin(a) * len / Double(steps)
            pts.append(P(x: x, y: y))
        }
        return pts
    }

    /// A stroke along the curl of a 2D noise field, curvature capped at
    /// 0.3 rad per step and leaning to the horizontal so nothing closes
    /// into a spiral.
    static func strokeFlow(
        _ x0: Double, _ y0: Double, _ len: Double, _ steps: Int, _ field: (Double, Double) -> Double,
        _ scale: Double, _ drift: Double
    ) -> [P] {
        var pts = [P(x: x0, y: y0)]
        var x = x0, y = y0
        var prev: Double? = nil
        for _ in 1...steps {
            let e = 0.5
            let dzdx = (field(x / scale + e / scale, y / scale) - field(x / scale - e / scale, y / scale)) / (2 * e)
            let dzdy = (field(x / scale, y / scale + e / scale) - field(x / scale, y / scale - e / scale)) / (2 * e)
            var a = atan2(-dzdx, dzdy)
            a = atan2(sin(a) * 0.55, cos(a) * 0.55 + 1.0) + drift
            if let p = prev {
                var d = a - p
                while d > Double.pi { d -= 2 * Double.pi }
                while d < -Double.pi { d += 2 * Double.pi }
                a = p + max(-0.3, min(0.3, d))
            }
            prev = a
            x += cos(a) * len / Double(steps)
            y += sin(a) * len / Double(steps)
            pts.append(P(x: x, y: y))
        }
        return pts
    }

    /// Weighted choice of a tint index.
    static func pick(_ R: inout LCG, _ weights: [Double]) -> Int {
        var s = 0.0
        let r = R.next() * weights.reduce(0, +)
        for i in 0..<weights.count {
            s += weights[i]
            if r < s { return i }
        }
        return weights.count - 1
    }

    /// `for (i = 0; i < n; i++)` with a fractional n: ceil(n) iterations.
    static func times(_ n: Double, _ body: () -> Void) {
        var i = 0.0
        while i < n { body(); i += 1 }
    }

    // MARK: Canvas

    /// A bitmap in points with the origin top left, like the mock-up's
    /// canvas, rendered at `scale` device pixels per point. Opaque for the
    /// pieces of the catalog; with alpha for the layers of the window, which
    /// are composed over black by the page.
    final class Canvas {
        let width: Double
        let height: Double
        /// The height the composition is placed in: the whole canvas, or the
        /// top part of a band that is painted taller than the row it is
        /// judged in. Motifs that fill a field ignore it; the tongues of the
        /// campfire, which rise from the lower half, are placed and counted
        /// within it.
        let focus: Double
        let scale: Double
        let context: CGContext

        init?(width: Double, height: Double, scale: Double, focus: Double? = nil, opaque: Bool = true) {
            self.width = width
            self.height = height
            self.focus = focus ?? height
            self.scale = scale
            let w = Int((width * scale).rounded()), h = Int((height * scale).rounded())
            let alpha: CGImageAlphaInfo = opaque ? .noneSkipLast : .premultipliedLast
            guard w > 0, h > 0,
                  let context = CGContext(data: nil, width: w, height: h, bitsPerComponent: 8, bytesPerRow: w * 4,
                                          space: Pigment.sRGB, bitmapInfo: alpha.rawValue)
            else { return nil }
            self.context = context
            context.translateBy(x: 0, y: CGFloat(height * scale))
            context.scaleBy(x: CGFloat(scale), y: CGFloat(-scale))
            context.setShouldAntialias(true)
            context.setAllowsAntialiasing(true)
            context.interpolationQuality = .high
        }

        func fill(_ tint: Tint, alpha: Double = 1, rect: CGRect? = nil) {
            context.setFillColor(tint.cgColor(alpha: alpha))
            context.fill(rect ?? CGRect(x: 0, y: 0, width: width, height: height))
        }

        func image() -> CGImage? { context.makeImage() }

        /// The bytes the bitmap holds.
        var bytes: Int { context.bytesPerRow * context.height }
    }
}
